  "glossary": [
    {
      "term": "AICTE",
      "fullForm": "All India Council for Technical Education",
      "meaning": "The central regulatory body for technical education; also runs national scholarships like Pragati and Saksham.",
      "relevance": "Source of central (non-Rajasthan-specific) scholarships."
    },
    {
      "term": "BTER",
      "fullForm": "Board of Technical Education, Rajasthan",
      "meaning": "The examining/curriculum board for diploma (polytechnic) programs.",
      "relevance": "Sets diploma syllabus and exam rules."
    },
    {
      "term": "BTU",
      "fullForm": "Bikaner Technical University",
      "meaning": "The affiliating university for B.Tech colleges mainly in northern/western Rajasthan.",
      "relevance": "Alternative to RTU depending on college location."
    },
    {
      "term": "CBCS",
      "fullForm": "Choice Based Credit System",
      "meaning": "The credit-based curriculum structure RTU uses for B.Tech programs.",
      "relevance": "Explains how B.Tech subjects/credits are organised."
    },
    {
      "term": "CEG",
      "fullForm": "Centre for Electronic Governance, Rajasthan",
      "meaning": "The government body that technically conducts/administers REAP counselling.",
      "relevance": "Runs the REAP portal and counselling rounds."
    },
    {
      "term": "DTE",
      "fullForm": "Directorate/Department of Technical Education, Rajasthan",
      "meaning": "The state government department that runs polytechnics and oversees engineering-college admissions.",
      "relevance": "The overall authority behind this workbook's data."
    },
    {
      "term": "EWS",
      "fullForm": "Economically Weaker Section",
      "meaning": "A reservation/income-based category for candidates outside SC/ST/OBC whose family income is below a set threshold.",
      "relevance": "Relevant to reservation-category questions."
    },
    {
      "term": "JEE Main",
      "fullForm": "Joint Entrance Examination (Main)",
      "meaning": "The national engineering entrance exam whose rank is the top-priority basis for REAP B.Tech seat allotment.",
      "relevance": "Most B.Tech aspirants' rank source."
    },
    {
      "term": "KM",
      "fullForm": "Kashmiri Migrant",
      "meaning": "A special-quota category in REAP counselling for displaced Kashmiri-migrant candidates.",
      "relevance": "Relevant to REAP quota rounds."
    },
    {
      "term": "Lateral Entry",
      "fullForm": "—",
      "meaning": "Direct admission into the 2nd year of a diploma or degree program (e.g., diploma-holders into 2nd year B.Tech).",
      "relevance": "Relevant to diploma-holders wanting to upgrade to a degree."
    },
    {
      "term": "NATA",
      "fullForm": "National Aptitude Test in Architecture",
      "meaning": "The entrance test used (with Class 12 marks) for B.Arch admission via REAP.",
      "relevance": "Relevant only to B.Arch applicants."
    },
    {
      "term": "NSP",
      "fullForm": "National Scholarship Portal",
      "meaning": "The central government's single online portal for applying to many central scholarships, including AICTE ones.",
      "relevance": "Where to apply for Pragati/Saksham."
    },
    {
      "term": "OBC / SBC / MBC / EBC",
      "fullForm": "Other / Special / Most / Extremely Backward Classes",
      "meaning": "State/central reservation categories, each with its own eligibility and income rules.",
      "relevance": "Relevant to category-based cutoff/scholarship/fee questions."
    },
    {
      "term": "PWD",
      "fullForm": "Person with Disability",
      "meaning": "A reservation/support category for candidates with a recognised disability.",
      "relevance": "Relevant to the Saksham scholarship and REAP's PWD quota."
    },
    {
      "term": "REAP",
      "fullForm": "Rajasthan Engineering Admission Process",
      "meaning": "The state's centralised counselling process for B.E./B.Tech/B.Arch admission — no separate entrance exam.",
      "relevance": "Use this process if you want a B.Tech/B.Arch seat."
    },
    {
      "term": "RTU",
      "fullForm": "Rajasthan Technical University, Kota",
      "meaning": "The affiliating university for most B.Tech colleges in central/southern Rajasthan.",
      "relevance": "Sets B.Tech curriculum/exams for its affiliated colleges."
    },
    {
      "term": "SC / ST",
      "fullForm": "Scheduled Caste / Scheduled Tribe",
      "meaning": "Constitutionally recognised reservation categories.",
      "relevance": "Relevant to reservation-category questions."
    },
    {
      "term": "SJE",
      "fullForm": "Department of Social Justice & Empowerment, Rajasthan",
      "meaning": "Runs the state's post-matric scholarship portal and schemes for SC/ST/OBC/EWS/PWD students.",
      "relevance": "Where most state scholarship applications happen."
    },
    {
      "term": "TFWS",
      "fullForm": "Tuition Fee Waiver Scheme",
      "meaning": "A quota that waives tuition fees for a limited number of meritorious/income-eligible students.",
      "relevance": "Ask about this if fee is a major concern."
    },
    {
      "term": "Upward Movement",
      "fullForm": "—",
      "meaning": "A counselling-round request to move to a better/preferred seat after an initial allotment, without losing the seat already held.",
      "relevance": "Relevant during multi-round counselling."
    }
  ],
